<?php
declare(strict_types=1);
require __DIR__ . '/_bootstrap.php';
$user=require_admin();$db=admin_db();$id=(int)($_GET['id']??$_POST['id']??0);
if(!$id){header('Location: /admin/?view=products');exit;}
$s=$db->prepare("SELECT p.id,p.image_path,l.slug line_slug,MAX(CASE WHEN t.locale='es' THEN t.name END) name_es FROM products p JOIN product_lines l ON l.id=p.line_id JOIN product_translations t ON t.product_id=p.id WHERE p.id=? AND p.deleted_at IS NULL GROUP BY p.id,p.image_path,l.slug");$s->execute([$id]);$product=$s->fetch();if(!$product){http_response_code(404);exit('Producto no encontrado');}
$error='';$saved=false;
if(($_SERVER['REQUEST_METHOD']??'')==='POST')try{
 verify_csrf();$pdf=save_document($db,$_FILES['technical_sheet']??[],(int)$user['id'])?:trim((string)($_POST['technical_sheet_path']??''));$db->beginTransaction();
 $db->prepare('INSERT INTO product_specs(product_id,scientific_name,tariff_code,caliber_es,caliber_en,destinations_es,destinations_en,technical_sheet_path) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE scientific_name=VALUES(scientific_name),tariff_code=VALUES(tariff_code),caliber_es=VALUES(caliber_es),caliber_en=VALUES(caliber_en),destinations_es=VALUES(destinations_es),destinations_en=VALUES(destinations_en),technical_sheet_path=VALUES(technical_sheet_path)')->execute([$id,trim((string)$_POST['scientific_name']),trim((string)$_POST['tariff_code']),trim((string)$_POST['caliber_es']),trim((string)$_POST['caliber_en']),trim((string)$_POST['destinations_es']),trim((string)$_POST['destinations_en']),$pdf]);
 foreach(['product_packages','product_certifications','product_harvest','product_relations'] as $table)$db->prepare("DELETE FROM $table WHERE product_id=?")->execute([$id]);
 $pack=$db->prepare('INSERT INTO product_packages(product_id,weight_primary,weight_secondary,material_es,material_en,package_type,sort_order) VALUES(?,?,?,?,?,?,?)');foreach(preg_split('/\R/',trim((string)$_POST['packages'])) as $i=>$line){if(!trim($line))continue;$v=array_pad(array_map('trim',explode('|',$line,5)),5,'');$type=in_array($v[4],['bag','sack','big-bag','other'],true)?$v[4]:'sack';$pack->execute([$id,$v[0],$v[1],$v[2],$v[3],$type,$i]);}
 $cert=$db->prepare('INSERT INTO product_certifications(product_id,name,sort_order) VALUES(?,?,?)');foreach(array_filter(array_map('trim',explode(',',(string)$_POST['certifications']))) as $i=>$name)$cert->execute([$id,$name,$i]);
 $harvest=$db->prepare('INSERT INTO product_harvest(product_id,month_number,availability) VALUES(?,?,?)');for($m=1;$m<=12;$m++){$v=$_POST['month'][$m]??'none';$harvest->execute([$id,$m,in_array($v,['none','harvest','available','limited'],true)?$v:'none']);}
 $relation=$db->prepare('INSERT INTO product_relations(product_id,related_product_id,sort_order) VALUES(?,?,?)');foreach(array_slice(array_values(array_filter(array_map('intval',$_POST['related']??[]))),0,3) as $i=>$rid)if($rid!==$id)$relation->execute([$id,$rid,$i]);
 if(!empty($_FILES['gallery']['name'][0])){foreach($_FILES['gallery']['name'] as $i=>$name){$file=['name'=>$name,'type'=>$_FILES['gallery']['type'][$i],'tmp_name'=>$_FILES['gallery']['tmp_name'][$i],'error'=>$_FILES['gallery']['error'][$i],'size'=>$_FILES['gallery']['size'][$i]];$path=save_upload($db,$file,(int)$user['id']);if($path)$db->prepare("INSERT INTO product_gallery(product_id,media_type,media_path,alt_es,alt_en,sort_order) VALUES(?,'image',?,?,?,?)")->execute([$id,$path,$product['name_es'],$product['name_es'],$i+10]);}}
 $video=trim((string)($_POST['video_url']??''));if($video&&filter_var($video,FILTER_VALIDATE_URL))$db->prepare("INSERT INTO product_gallery(product_id,media_type,media_path,sort_order) VALUES(?,'video',?,99)")->execute([$id,$video]);
 audit($db,(int)$user['id'],'save','product-details',$id);$db->commit();$saved=true;
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}
$s=$db->prepare('SELECT * FROM product_specs WHERE product_id=?');$s->execute([$id]);$spec=$s->fetch()?:['scientific_name'=>'','tariff_code'=>'','caliber_es'=>'','caliber_en'=>'','destinations_es'=>'','destinations_en'=>'','technical_sheet_path'=>''];
$s=$db->prepare('SELECT * FROM product_packages WHERE product_id=? ORDER BY sort_order');$s->execute([$id]);$packages=implode("\n",array_map(fn($p)=>implode('|',[$p['weight_primary'],$p['weight_secondary'],$p['material_es'],$p['material_en'],$p['package_type']]),$s->fetchAll()));
$s=$db->prepare('SELECT name FROM product_certifications WHERE product_id=? ORDER BY sort_order');$s->execute([$id]);$certifications=implode(', ',array_column($s->fetchAll(),'name'));
$s=$db->prepare('SELECT month_number,availability FROM product_harvest WHERE product_id=?');$s->execute([$id]);$months=array_column($s->fetchAll(),'availability','month_number');
$s=$db->prepare('SELECT related_product_id FROM product_relations WHERE product_id=? ORDER BY sort_order');$s->execute([$id]);$selected=array_map('intval',array_column($s->fetchAll(),'related_product_id'));
$others=$db->query("SELECT p.id,MAX(CASE WHEN t.locale='es' THEN t.name END) name FROM products p JOIN product_translations t ON t.product_id=p.id WHERE p.deleted_at IS NULL AND p.is_active=1 GROUP BY p.id ORDER BY name")->fetchAll();
$gallery=$db->prepare('SELECT * FROM product_gallery WHERE product_id=? ORDER BY sort_order,id');$gallery->execute([$id]);$gallery=$gallery->fetchAll();$monthNames=['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ficha de <?=e($product['name_es'])?> | Royal Beans</title><link rel="stylesheet" href="/admin/admin.css"></head><body class="admin-body"><aside class="admin-sidebar"><a class="admin-brand" href="/admin/"><img src="/images/logo.webp" alt=""><span><strong>ROYAL BEANS</strong><small>ADMINISTRACIÓN</small></span></a><nav><a href="/admin/">Resumen</a><a class="active" href="/admin/?view=products">Productos</a><a href="/admin/editor.php">Editor visual</a><a href="/admin/?view=media">Imágenes</a></nav><div class="admin-user"><strong><?=e($user['name'])?></strong><a href="/admin/?view=logout">Cerrar sesión</a></div></aside><main class="admin-main"><header class="admin-top"><div><p class="admin-eyebrow">Ficha comercial</p><h1><?=e($product['name_es'])?></h1></div><a class="site-button" href="/productos/linea-<?=$product['line_slug']==='retail'?'retail':'convencional'?>/" target="_blank">Ver línea ↗</a></header><?php if($saved):?><div class="alert">Ficha actualizada.</div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data" class="admin-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><section class="admin-panel"><h2>Datos técnicos</h2><div class="form-grid"><label>Nombre científico<input name="scientific_name" value="<?=e($spec['scientific_name'])?>"></label><label>Partida arancelaria<input name="tariff_code" value="<?=e($spec['tariff_code'])?>"></label><label>Calibre (ES)<input name="caliber_es" value="<?=e($spec['caliber_es'])?>"></label><label>Caliber (EN)<input name="caliber_en" value="<?=e($spec['caliber_en'])?>"></label><label>Destinos principales (ES)<input name="destinations_es" value="<?=e($spec['destinations_es'])?>"></label><label>Main destinations (EN)<input name="destinations_en" value="<?=e($spec['destinations_en'])?>"></label><label>Ruta actual del PDF<input name="technical_sheet_path" value="<?=e($spec['technical_sheet_path'])?>"></label><label>Ficha técnica PDF<input type="file" name="technical_sheet" accept="application/pdf"><small>PDF, máximo 12 MB.</small></label></div></section><section class="admin-panel"><h2>Galería</h2><div class="media-grid"><?php foreach($gallery as $item):?><article><?php if($item['media_type']==='image'):?><img src="<?=e($item['media_path'])?>" alt=""><?php else:?><div><?=e($item['media_path'])?></div><?php endif;?></article><?php endforeach;?></div><div class="form-grid"><label>Nuevas imágenes<input type="file" name="gallery[]" multiple accept="image/jpeg,image/png,image/webp,image/avif"><small>Recomendado: 1400 × 1050 px (4:3).</small></label><label>Video (YouTube o Vimeo)<input type="url" name="video_url"></label></div></section><section class="admin-panel"><h2>Empaques y certificaciones</h2><label>Empaques, uno por línea<textarea name="packages" rows="5" placeholder="25 kg|50 lb|Polipropileno|Polypropylene|sack"><?=e($packages)?></textarea><small>Formato: peso principal | peso secundario | material ES | material EN | bag, sack, big-bag u other.</small></label><label>Certificaciones separadas por coma<input name="certifications" value="<?=e($certifications)?>"></label></section><section class="admin-panel"><h2>Calendario de cosecha y disponibilidad</h2><div class="month-editor"><?php foreach($monthNames as $i=>$name):$m=$i+1;?><label><?=$name?><select name="month[<?=$m?>]"><?php foreach(['none'=>'Sin disponibilidad','harvest'=>'Cosecha','available'=>'Disponible','limited'=>'Limitado'] as $v=>$label):?><option value="<?=$v?>" <?=($months[$m]??'none')===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><?php endforeach;?></div></section><section class="admin-panel"><h2>Productos relacionados</h2><p>Selecciona hasta tres.</p><div class="related-editor"><?php foreach($others as $item):if((int)$item['id']===$id)continue;?><label class="check"><input type="checkbox" name="related[]" value="<?=$item['id']?>" <?=in_array((int)$item['id'],$selected,true)?'checked':''?>> <?=e($item['name'])?></label><?php endforeach;?></div></section><div class="form-actions"><a href="/admin/?view=products">Volver</a><button class="primary-button">Guardar ficha completa</button></div></form></main><style>.month-editor{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.month-editor label,.related-editor label{display:grid;gap:5px;font-size:12px;font-weight:700}.month-editor select{width:100%;padding:10px;border:1px solid var(--line);border-radius:7px}.related-editor{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.admin-panel>label{display:grid;gap:7px;margin-top:16px;font-size:13px;font-weight:650}.admin-panel>label input,.admin-panel>label textarea{width:100%;padding:12px;border:1px solid var(--line);border-radius:8px}@media(max-width:850px){.month-editor{grid-template-columns:repeat(2,1fr)}.related-editor{grid-template-columns:1fr}}</style></body></html>
